def style(trait, s, pol='pos'):
    r = random.random()
    if pol == 'neg':
        if trait == 'hype':
            return s + random.choice([' 😬',' 😭',' 💀','...','']) if r < 0.5 else s
        if trait == 'wholesome':
            return s + random.choice([' 💔',' 🥺',' 😔']) if r < 0.5 else s
        if trait == 'mogul':
            return s + random.choice([' 📉',' 🚩']) if r < 0.4 else s
    if trait == 'hype':
        if r < 0.22 and len(s) < 70: return s.upper()
        if r < 0.5: return s + random.choice([" 🔥"," 😭"," 🙌","!!","!!!"])
        return s
    if trait == 'chaos':
        if r < 0.35: return s.lower().replace(".","").replace(",","")
        if r < 0.55: return s + random.choice([" 💀"," 💀💀"," 😭"," 🤡"," ☠️"])
        return s
    if trait == 'hater':
        if r < 0.5: return s.lower()
        if r < 0.65: return s + random.choice(["."," 🙄"," 💅","..."])
        return s
    if trait == 'wholesome':
        if r < 0.4: return s + random.choice([" 💛"," 🥹"," ✨"," 🌷"," 🫶"])
        return s
    if trait == 'gossip':
        if r < 0.4: return s + random.choice([" 👀"," 🍵"," 😮‍💨"," 🤫"])
        return s
    if trait == 'mogul':
        if r < 0.3: return s + random.choice([" 📈"," 💼"," 💰"])
        return s
    return s


# ======================================================================================
# Wild-west layer: cussing, roasts, nitpicks, unhinged hype, hot arguments, hostile DMs, rants.
# Every line is built from phrase pools + slot grammars, so the corpus reaches millions of
# distinct lines while the generator stays tiny. Runs in CI before the app is built.
# ======================================================================================
SLOTS = {
 'A': ["pathetic","delusional","braindead","insufferable","washed","fucking embarrassing","goddamn useless","tone-deaf","dogshit","completely cooked","straight-up trash","clown-ass","miserable","unwatchable","unbearable","cringe as hell","painfully mid","fake as hell","exhausting","shameless","brain-rotted","chronically online","terminally unfunny","clueless","bargain-bin","low-effort","fucked up","shitty","soulless"],
 'N': ["clown","dumbass","jackass","fraud","wannabe","loser","bozo","hack","poser","grifter","NPC","menace","disgrace","walking L","tryhard","sellout","dipshit","asshole","prick","douchebag","moron","idiot","muppet","joke","fake-ass influencer","attention addict","reply guy","bot","coward","parasite","goofy-ass clown","knockoff"],
 'U': ["holy shit","what the fuck","jesus christ","oh my god","bruh","damn","god damn","are you fucking serious","wow","seriously","no fucking way","what the hell","christ almighty","oh for fuck's sake"],
 'F': ["fucking","goddamn","straight up","actually","genuinely","absolutely","literally","honestly","legitimately","unbelievably","painfully","disgustingly"],
 'V': ["shut the fuck up","log the fuck off","delete this shit","touch some goddamn grass","get a fucking life","sit the fuck down","crawl back under your rock","go bother someone else","take this L and leave","stay in your lane","go cry about it","pack it up","uninstall the app","go outside for once"],
 'P': ["beautiful","iconic","legendary","unreal","insane","fire","perfect","unmatched","filthy","criminal","sick","ridiculous","stupid good","disgustingly good","obscene","unholy","elite","untouchable"],
 'W': ["banger","masterpiece","W","flex","clinic","heater","ten out of ten","piece of art","lesson","moment","bar","highlight"],
}

def expand(t, k=4):
    keys = re.findall(r"\{([ANUFVPW])\}", t)
    if not keys:
        return [t]
    out = set()
    for _ in range(k * 4):
        s = t
        for key in keys:
            s = s.replace("{%s}" % key, random.choice(SLOTS[key]), 1)
        out.add(s)
        if len(out) >= k:
            break
    return list(out)

