SPEC = [  # bucket, pool, polarity, per-trait line target
 ('roast.hard', 'hot', 'neg', 75000),
 ('roast.nitpick', 'hot', 'neg', 55000),
 ('hype.max', 'max', 'pos', 65000),
 ('rebut.fight.hot', 'hot', 'neg', 75000),
 ('rebut.defend', 'hot', 'neg', 50000),
 ('dm.hostile', 'hot', 'neg', 55000),
 ('post.subtweet', 'hot', 'neg', 50000),
 ('post.rant', 'hot', 'neg', 55000),
 ('post.hype', 'max', 'pos', 40000),
]
SCALE = float(sys.argv[2]) if len(sys.argv) > 2 else 1.0

BANNED = re.compile(r"\b(nigg|fagg|retard|cunt|kys|kill yourself|rape|rapist|tranny|chink|spic|kike|coon|nazi)", re.I)

def build_cell(trait, bucket, pool, pol, target):
    if pool == 'hot':
        opens = HOT_OPEN[trait] + SH_HOT_OPEN
        tails = HOT_TAIL[trait] + SH_HOT_TAIL
    else:
        opens = MAX_OPEN[trait] + SH_MAX_OPEN
        tails = MAX_TAIL[trait] + SH_MAX_TAIL
    opens = opens + [""] * 10
    tails = tails + [""] * 10
    cores = []
    for tpl in T[bucket]:
        cores.extend(expand(tpl, 4))
    target = int(target * SCALE)
    space = len(opens) * len(cores) * len(tails)
    target = min(target, int(space * 0.6))
    seen = set()
    guard = 0
    while len(seen) < target and guard < target * 6:
        guard += 1
        o = opens[random.randrange(len(opens))]
        c = cores[random.randrange(len(cores))]
        t = tails[random.randrange(len(tails))]
        sep1 = random.choice([", ", " - ", ": ", "... ", " "]) if o else ""
        if o.endswith((",", ":", "...", ".", "!", "?")): sep1 = " "
        if t:
            sep2 = " " if not t[0].isalpha() else random.choice([". ", " - ", "... ", ", ", " — "])
        else:
            sep2 = ""
        line = (o + sep1 + c + sep2 + t).strip()
        line = style(trait, line, pol).replace("\n", " ")
        line = re.sub(r"\b([Aa]) (?=[aeiouAEIOU])", r"\1n ", line)
        seen.add(line)
    return list(seen)

total = 0
out = []
for trait in OPEN:
    # --- original six buckets ---
    for bucket, cores in CORES.items():
        pol = POL[bucket]
        opens = OPEN[trait][pol] + [""]
        tails = TAIL[trait][pol] + [""]
        combos = list(itertools.product(opens, cores, tails))
        random.shuffle(combos)
        keep = int(len(combos) * 0.94 * min(1.0, SCALE))
        lines = set()
        for o, c, t in combos[:keep]:
            sep1 = random.choice([", ", " - ", ": ", "... ", " "]) if o else ""
            if t:
                sep2 = " " if not t[0].isalpha() else random.choice([". ", " - ", "... ", ", ", " — "])
            else:
                sep2 = ""
            if o.endswith((",", ":", "...", ".")): sep1 = " "
            line = (o + sep1 + c + sep2 + t).strip()
            line = style(trait, line, pol)
            lines.add(line.replace("\n", " "))
        out.append("@@%s|%s" % (trait, bucket))
        out.extend(sorted(lines, key=lambda x: random.random()))
        total += len(lines)
    # --- wild-west buckets ---
    for bucket, pool, pol, target in SPEC:
        lines = build_cell(trait, bucket, pool, pol, target)
        out.append("@@%s|%s" % (trait, bucket))
        out.extend(lines)
        total += len(lines)

bad = [l for l in out if not l.startswith("@@") and BANNED.search(l)]
if bad:
    raise SystemExit("banned term in corpus: %r" % bad[:3])
with open(OUT, 'w', encoding='utf-8') as f:
    f.write("\n".join(out) + "\n")
print("lines:", total)
